WITH cycle AS (
  INSERT INTO emma_cycles (mode, thoughts, actions) VALUES ($1, $2, $3::jsonb) RETURNING id
), usage AS (
  INSERT INTO llm_usage (workflow, input_chars, output_chars, est_cost_eur) VALUES ('COGNITIVE_LOOP', $4, $5, emma_llm_cost($4, $5))
), cal AS (
  INSERT INTO emma_action_log (cycle_id, action_type, ok, detail) SELECT (SELECT id FROM cycle), 'calendar_read', false, $6::text WHERE $6::text <> ''
)
SELECT (SELECT id FROM cycle) AS cycle_id;

