// Ergebnis jeder Aktion feststellen – Fehler werden als Fehler geloggt, nicht als erledigt.
return $input.all().map((item, i) => {
  const a = $('Aktion?').itemMatching(i)?.json || {};
  const ok = !item.json.error;
  return { json: { cycle_id: a.cycle_id, type: a.type || a.kind, ok,
    detail: ok ? JSON.stringify(item.json).slice(0, 500) : String(item.json.error?.message || item.json.error).slice(0, 500) } };
});

const p = $('Aktionen prüfen').first().json;
const d = $input.first().json;
const c = $('Kontext laden (core-os)').first().json || {};
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const day = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
const time = t => new Date(t).toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' });
const LABEL = { schedule_wake: '⏰ Weckzeit', create_task: '📋 Aufgabe', complete_task: '✅ Erledigt', remember: '🧠 Gemerkt', propose: '📝 Vorschlag' };
const describe = a => (LABEL[a.type] || a.type) + ': ' + (a.summary || a.title || a.content || a.id || '');
const L = [];
if (p.mode === 'MORNING') {
  const termine = $('Irinas Termine (24h)').all().map(i => i.json).filter(e => e.id)
    .map(e => `- ${e.start?.dateTime ? time(e.start.dateTime) : 'ganztägig'} ${e.summary || ''}`);
  L.push(`Briefing – ${day}`, '', 'Emmas Gedanken:', p.thoughts, '', 'Termine heute:', ...(termine.length ? termine : ['- keine']));
  L.push('', 'Heute geplant:', ...(p.actions.length ? p.actions.map(a => '- ' + describe(a)) : ['- nichts Konkretes']));
  L.push('', 'Wartet auf deine Freigabe (in core-os):', ...list(d.proposals).filter(q => q.status === 'proposed').map(q => `- #${q.id} ${q.summary}`));
  L.push('', 'Offene Aufgaben (core-os):', ...(Array.isArray(c.tasks) && c.tasks.length ? c.tasks.map(t => '- ' + (t.title || t)) : ['- keine']));
} else {
  L.push(`Arbeitsprotokoll – ${day}`, '');
  for (const cy of list(d.cycles)) {
    const acts = (typeof cy.actions === 'string' ? JSON.parse(cy.actions) : cy.actions)?.planned || [];
    L.push(`${time(cy.created_at)} (${cy.mode}): ${cy.thoughts}`, ...acts.map(a => '   → ' + describe(a)));
  }
  L.push('', 'Ergebnisse:', ...(list(d.action_log).map(l => `- ${l.ok ? '✅' : '❌'} ${l.action_type} ${l.ok ? '' : '– ' + l.detail}`)), ...(list(d.action_log).length ? [] : ['- keine']));
  L.push('', 'Vorschläge heute:', ...(list(d.proposals).map(q => `- #${q.id} ${q.summary} [${q.status}]`)), ...(list(d.proposals).length ? [] : ['- keine']));
  L.push('', 'Erstellte Spuren:', ...(list(d.artifacts).map(a => `- [${a.kind}] ${a.title} ${a.url || ''}`)), ...(list(d.artifacts).length ? [] : ['- keine']));
}
L.push('', `KI-Kosten diesen Monat (Schätzung): ${Number(d.spent_month || 0).toFixed(2)} €`);
const date = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
return [{ json: {
  title: (p.mode === 'MORNING' ? 'Briefing ' : 'Arbeitsprotokoll ') + date,
  content: L.join('\n'),
  kind: p.mode === 'MORNING' ? 'briefing' : 'protokoll',
  folder: p.mode === 'MORNING' ? $('Konfiguration').first().json.drive_briefings : $('Konfiguration').first().json.drive_logs,
} }];

